from datetime import datetime, timezone
from decimal import Decimal
from ledgerly.adjustments import outage_refund
from ledgerly.errors import BillingError
from ledgerly.models import Payment
from ledgerly import audit

T0 = datetime(2026,10,1,tzinfo=timezone.utc)
def mk(status="captured", amt="80.00"):
    return Payment("p","i",Decimal(amt),status=status,created_at=T0,captured_at=T0)

# partial then full
p=mk(); outage_refund(p,Decimal("30.00"),T0); assert p.status=="captured"
outage_refund(p,Decimal("50.00"),T0); assert p.status=="refunded" and p.refunded_amount==Decimal("80.00")
print("full refund ok", p.status, p.refunded_amount)

# over refund
p=mk(); outage_refund(p,Decimal("50.00"),T0)
try: outage_refund(p,Decimal("31.00"),T0); print("FAIL")
except BillingError as e: print("over:", e.code)

# non-captured
for st in ("authorized","voided","refunded"):
    try: outage_refund(mk(st),Decimal("1.00"),T0); print("FAIL",st)
    except BillingError as e: print(st, e.code)

# non-positive
for a in ("0","-1"):
    try: outage_refund(mk(),Decimal(a),T0); print("FAIL")
    except BillingError as e: print("amount",a,e.code)

# naive datetime
try: outage_refund(mk(),Decimal("1.00"),datetime(2026,10,1)); print("FAIL")
except BillingError as e: print("naive:", e.code)

# audit
print("audit:", audit.events("payment_refunded")[-1]["event"])
EOF"}

